import * as React from "react";
import "./TimelineInfoDescription.scss";

export interface TimelineInfoDescriptionProps {
  title: React.ReactNode;
  subtitle: React.ReactNode;
}

const TimelineInfoDescription = ({
  title,
  subtitle,
}: TimelineInfoDescriptionProps) => {
  return (
    <div className="timeline-info-desc">
      <div className="timeline-info-title">{title}</div>
      <div>{subtitle}</div>
    </div>
  );
};

export default TimelineInfoDescription;
